insert into execution_plan (
    id, project_id, name, status, environment_key, trigger_policy_json, dag_digest,
    description, created_by, updated_by, archived_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{name}, #{status}, #{environmentKey},
    cast(coalesce(#{triggerPolicyJson}, '{}') as jsonb),
    #{dagDigest}, #{description}, #{createdBy}, #{updatedBy}, #{archivedAt}, #{createdAt}, #{updatedAt}
)

insert into execution_run (
    id, plan_id, project_id, status, trigger_type, request_key, source_event_id, attempt, trace_id,
    result_summary_json, error_code, error_summary, created_by, started_at, finished_at, created_at, updated_at
) values (
    #{id}, #{planId}, #{projectId}, #{status}, #{triggerType}, #{requestKey}, #{sourceEventId},
    #{attempt}, #{traceId}, cast(coalesce(#{resultSummaryJson}, '{}') as jsonb),
    #{errorCode}, #{errorSummary}, #{createdBy}, #{startedAt}, #{finishedAt}, #{createdAt}, #{updatedAt}
)
on conflict do nothing

insert into execution_node_run (
    id, run_id, plan_node_id, status, attempt, runner_type, external_run_id, error_code, error_summary,
    result_summary_json, heartbeat_at, queued_at, started_at, finished_at, created_at, updated_at
) values (
    #{id}, #{runId}, #{planNodeId}, #{status}, #{attempt}, #{runnerType}, #{externalRunId},
    #{errorCode}, #{errorSummary}, cast(coalesce(#{resultSummaryJson}, '{}') as jsonb),
    #{heartbeatAt}, #{queuedAt}, #{startedAt}, #{finishedAt}, #{createdAt}, #{updatedAt}
)

